export function middleware(req) {
  const role = req.cookies.get('role');
  if (role === 'admin') {
    return NextResponse.redirect('/admin');
  } else if (role === 'user') {
    return NextResponse.redirect('/dashboard');
  }
  return NextResponse.next();
}

